import { NextRequest } from "next/server";
import { buildEntityMarkdown, markdownResponse } from "@/lib/agent-markdown";

// Legacy LLM endpoint (referenced from llms.txt and external citations).
// Content is generated by the shared agent-markdown layer so it stays in sync
// with the .md twins and content negotiation.
export async function GET(request: NextRequest) {
    const sp = request.nextUrl.searchParams;
    const city = sp.get("city");
    const vehicle = sp.get("vehicle");
    const md = buildEntityMarkdown({
        city,
        vehicle,
        hazard: sp.get("hazard"),
        road: sp.get("road"),
        neighborhood: sp.get("neighborhood"),
        light: sp.get("light"),
    });
    const canonical = city ? (vehicle ? `/${city}/${vehicle}` : `/${city}`) : "/";
    return markdownResponse(md, canonical);
}
